const input = $input.first().json;
const body = (typeof input.body === 'object' && input.body !== null) ? input.body : input;
const required = ['application_id', 'dealer_name', 'full_name', 'email', 'admin_notes'];
const missing = required.filter(f => !body[f]);

if (missing.length) return [{ json: { ok: false, missing } }];

return [{
  json: {
    ok: true,
    application_id: body.application_id,
    dealer_name:    body.dealer_name,
    full_name:      body.full_name,
    email:          body.email,
    admin_notes:    body.admin_notes,
    admin_url:      body.admin_url || ''
  }
}];

const d = $input.first().json;
const MAIL_FROM   = process.env.MAIL_FROM   || 'Black Label Market <no-reply@blacklabelmarket.es>';
const ADMIN_EMAIL = process.env.ADMIN_EMAIL || 'aldeiaceo@gmail.com';
const MARKET_URL  = process.env.MARKET_URL  || 'https://blacklabelmarket.es';

const notesHtml = d.admin_notes
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
  .replace(/\n/g, '<br>');

const emailHtml = `<p>Hola ${d.full_name},</p>
<p>Hemos revisado la solicitud de alta de <strong>${d.dealer_name}</strong> en Black Label Market y nos gustaría obtener alguna información adicional antes de continuar con el proceso.</p>
<blockquote style="border-left:3px solid #c9a227;padding-left:12px;margin:16px 0;color:#555">${notesHtml}</blockquote>
<p>Por favor, responde a este email con la información solicitada o, si lo prefieres, puedes contactarnos directamente.</p>
<p>Quedamos a tu disposición.<br>El equipo de Black Label Market</p>`;

return [{
  json: {
    ...d,
    emailPayload: {
      from: MAIL_FROM, to: [d.email],
      subject: `Solicitud de alta — necesitamos información adicional`,
      html: emailHtml
    },
    slackText: `*🟡 Solicitud de más info enviada*\n\n*Showroom:* ${d.dealer_name}\n*Contacto:* ${d.full_name} (${d.email})${d.admin_url ? '\n' + d.admin_url : ''}`
  }
}];
